"""Advisory decisions generated by program rules, never model instructions."""

from sql_optimization_agent.performance import validation_passed


def attach_recommendation(report):
    status=report.get('status')
    if status in ('result_mismatch','membership_mismatch','count_mismatch','invalid_suggestion'):
        decision,reason='keep_original','candidate_rejected'
    elif status in ('no_suggestion','no_rewrite'):
        decision,reason='keep_original','model_kept_original'
    elif status!='completed':
        decision,reason='not_evaluated','evaluation_error'
    elif not validation_passed(report):
        decision,reason='not_evaluated','validation_not_confirmed'
    else:
        assessment=report.get('performance_assessment') or {}
        verdict=assessment.get('verdict')
        if verdict=='improved':
            decision,reason='use_candidate','validated_and_improved'
        elif verdict in ('regressed','inconclusive'):
            decision,reason='keep_original','performance_'+verdict
        else:
            decision,reason='not_evaluated','performance_not_assessed'
    return {**report,'recommendation':{'decision':decision,'reason_code':reason,'advisory_only':True}}
